10	#define WINDOW_ID 1UL
11	
12	static struct XshimPixmap *pixmap_of(Pixmap p) {
13	  return (p == None || p == WINDOW_ID) ? NULL : (struct XshimPixmap *)(uintptr_t)p;
14	}
15	
16	static void pixmap_free(struct XshimPixmap *pm) {
17	  if (!pm) return;
18	  free(pm->rgb);
19	  free(pm->bits);
20	  free(pm);
21	}
22	
23	static struct XshimPixmap *pixmap_new(int w, int h, int depth) {
24	  struct XshimPixmap *pm = (struct XshimPixmap *)calloc(1, sizeof(*pm));
25	  if (!pm) return NULL;
26	  pm->w = w;
27	  pm->h = h;
28	  pm->depth = depth;
29	  pm->stride = (w + 7) / 8;
30	  if (depth == 1)
31	    pm->bits = (uint8_t *)malloc((size_t)pm->stride * (size_t)h);
32	  else
33	    pm->rgb = (uint16_t *)malloc((size_t)w * (size_t)h * sizeof(uint16_t));
34	  if (!pm->bits && !pm->rgb) {
35	    pixmap_free(pm);
36	    return NULL;
37	  }
38	  return pm;
39	}
