  glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
  glEnable(GL_BLEND);
  fill_everything_with(1, 0, 0, 0);
  TEST_ASSERT_EQUAL_HEX16(rgb565(255, 0, 0), centre_pixel());
